INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', '€1,000-3,000', 'Core Art. 24 fine range for legal entities');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE code = 'SI';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Format & channels', '[["B2B invoice format", "e-SLOG 2.0 -- Slovenia''s own EN 16931-aligned XML standard, maintained by GZS (Chamber of Commerce and Industry)"], ["B2B exchange model", "Decentralized -- no single mandatory government clearance platform for B2B, unlike UJP''s role in B2G"], ["Permitted channels (ZIERDED Art. 9)", "Certified e-path (\"e-pot\") provider; direct system-to-system link; or Peppol"], ["B2G invoice format", "Also e-SLOG, submitted via UJP''s EVIT hub (banks, contracted processors, or the e-Racuni portal)"]]', 'ZIERDED does not name a single mandatory transmission network the way some CTC-model countries do -- businesses choose among the three permitted channels, so your choice of provider matters more in Slovenia than in a single-platform regime.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE code = 'SI';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'UJP''s role in B2G', '[["EVIT hub", "UJP operates the \"enotna vstopna in izstopna tocka\" (single entry/exit point) for budget-user e-invoice exchange"], ["e-Racuni portal", "Free submission route for suppliers without a bank or contracted processor -- https://eracuni.ujp.gov.si/"], ["Bank / processor routes", "Participating banks and UJP-contracted data processors can also carry e-invoices to budget users"], ["Peppol Authority status", "Not established -- no source confirms Slovenia has a formally registered OpenPeppol Peppol Authority"]]', 'UJP is sometimes described informally as Slovenia''s "Peppol Authority" -- that title does not appear on OpenPeppol''s own current authorities list, and UJP''s government page describes its role as the EVIT hub operator, not a Peppol governance body. Treat UJP as the B2G hub, not a confirmed Peppol Authority, until a primary source says otherwise.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 0 FROM countries WHERE code = 'SI';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Who ZIERDED covers', '[["Scope (Art. 7)", "Every entity registered in Slovenia''s Business Register, and every self-employed person"], ["Size threshold", "None found -- the law applies uniformly, with no small-business carve-out identified in the gazette text"], ["Consumer invoices", "Covered separately, under the lower Art. 25 penalty range rather than Art. 24"], ["Public sector (B2G)", "Already covered separately since 2015 under ZOPSPU/ZOPSPU-A -- ZIERDED is a B2B-focused addition, not a replacement"]]', 'ZIERDED Art. 1 explicitly ties the law to transposing elements of the EU''s ViDA directive (2025/516) -- expect further detail (e.g. any future digital reporting requirement) to develop as ViDA''s own e-invoicing/digital-reporting pillar phases in across the EU toward 2030.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 1 FROM countries WHERE code = 'SI';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'The two-stage rollout', '[["1 April 2027", "ZIERDED Chapter 4''s certified e-path provider regime takes effect -- providers can seek certification and businesses can begin using certified providers"], ["1 January 2028", "The core mandatory exchange obligation applies to all in-scope entities, across all three permitted channels"], ["No pre-2027 registration requirement found", "Nothing in the gazette text requires businesses to register or prepare formally before the 2027 date"]]', NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 0 FROM countries WHERE code = 'SI';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '⚠️ Core exchange violations (Art. 24)', NULL, NULL, 'ZIERDED Art. 24 sets the core penalty range for failing to comply with the mandatory B2B exchange obligation once it applies: EUR 1,000-3,000 for legal entities, EUR 500-1,500 for sole proprietors, and EUR 100-500 for a responsible person within an organization. These figures were independently confirmed by direct fetch of the Official Gazette text in this session, not carried over from a secondary source.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE code = 'SI';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🧾 Consumer-invoice violations (Art. 25)', NULL, NULL, 'A separate, lower penalty range applies specifically to consumer-invoice violations under Art. 25: EUR 500-1,500 for legal entities, EUR 100-500 for sole proprietors, and EUR 50-250 for a responsible person. This is a distinct violation category from Art. 24''s core B2B exchange fines, not an alternative or reduced version of the same fine.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 2 FROM countries WHERE code = 'SI';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🔍 What we could not confirm', NULL, NULL, 'ZIERDED''s penalty articles are new law -- there is no enforcement track record yet to cite the way Costa Rica''s or Jordan''s deep dives can. Two secondary-only claims sometimes repeated about Slovenia''s e-invoicing ecosystem -- that ZZI operates a formally branded "Exchange Hub," and that FURS offers a "miniBlagajna" tool usable in this context -- were not independently corroborated on a primary government page in this round of research and are deliberately left out of this page rather than repeated as fact.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 0 FROM countries WHERE code = 'SI';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Confirm your current B2G e-invoicing route, if you sell to Slovenian public bodies', 'Check whether your business already reaches Slovenian budget users through a bank, a UJP-contracted processor, or the UJP e-Racuni portal -- this obligation has applied since 2015 and is separate from the new B2B law.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 1 FROM countries WHERE code = 'SI';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Read ZIERDED''s official text before choosing a B2B exchange channel', 'The law permits three channels -- a certified e-path provider, a direct system-to-system link, or Peppol -- with no single mandatory platform; understand the trade-offs before committing.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 2 FROM countries WHERE code = 'SI';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Confirm your invoicing software can produce e-SLOG 2.0 / EN 16931-compliant output', 'e-SLOG 2.0 is Slovenia''s national standard for both the existing B2G obligation and the new B2B law -- confirm your provider supports it rather than assuming generic EN 16931 support is sufficient.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 3 FROM countries WHERE code = 'SI';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'If choosing a certified e-path provider, wait for the 1 April 2027 certification regime before selecting one', 'ZIERDED''s Chapter 4 certification rules only take effect on this date -- confirm any provider''s certification is actually in force under the regime before relying on it.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 4 FROM countries WHERE code = 'SI';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Test your chosen exchange channel well ahead of 1 January 2028', 'The core mandatory exchange obligation applies to essentially all Business-Register-registered entities and self-employed persons from this date, with real fines under Art. 24/25 for non-compliance -- don''t leave testing until the deadline.');
